import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    SphereGeometry,
    Color,
    PointLight,
  } = THREE;

  const root = new Group();
  root.name = 'features-ornamental-divider';

  const content = new Group();
  content.name = 'divider-content';
  root.add(content);

  const resources = [];
  const timelines = [];
  const disposables = [];

  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true,
  });
  backdropMaterial.colorNode = mix(
    uniform(surface),
    uniform(ink),
    uv().y
  );

  const backdrop = new Mesh(new PlaneGeometry(7, 6, 1, 1), backdropMaterial);
  backdrop.name = 'designed-dark-backdrop';
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdrop.material);

  const backingMaterial = new MeshStandardNodeMaterial({
    color: surface,
    metalness: 0.42,
    roughness: 0.62,
  });

  const backing = new Mesh(
    new BoxGeometry(2.9, 0.16, 0.055),
    backingMaterial
  );
  backing.name = 'machined-divider-backplate';
  backing.position.z = -0.055;
  content.add(backing);
  disposables.push(backing.geometry, backing.material);

  const ruleMaterial = new MeshStandardNodeMaterial({
    color: paper,
    metalness: 0.5,
    roughness: 0.56,
  });

  const rule = new Mesh(
    new BoxGeometry(2.72, 0.026, 0.075),
    ruleMaterial
  );
  rule.name = 'machined-rule';
  rule.position.z = 0.01;
  content.add(rule);
  disposables.push(rule.geometry, rule.material);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });

  const focusEdge = new Mesh(
    new BoxGeometry(2.78, 0.012, 0.09),
    edgeMaterial
  );
  focusEdge.name = 'accent-focus-edge';
  focusEdge.position.set(0, 0.037, 0.055);
  content.add(focusEdge);
  disposables.push(focusEdge.geometry, focusEdge.material);

  const endMaterial = new MeshStandardNodeMaterial({
    color: ink,
    metalness: 0.5,
    roughness: 0.58,
  });

  const leftEnd = new Mesh(
    new BoxGeometry(0.12, 0.075, 0.12),
    endMaterial
  );
  leftEnd.position.set(-1.37, 0, 0.025);
  leftEnd.rotation.z = Math.PI / 4;
  content.add(leftEnd);

  const rightEnd = leftEnd.clone();
  rightEnd.position.x = 1.37;
  content.add(rightEnd);
  disposables.push(leftEnd.geometry, leftEnd.material);

  const jewelMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.35,
    metalness: 0.22,
    roughness: 0.34,
  });

  const jewel = new Mesh(
    new SphereGeometry(0.105, 24, 16),
    jewelMaterial
  );
  jewel.name = 'center-signal-jewel';
  jewel.position.set(0, 0, 0.105);
  content.add(jewel);
  disposables.push(jewel.geometry, jewel.material);

  const jewelCoreMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.82,
  });

  const jewelCore = new Mesh(
    new SphereGeometry(0.035, 16, 12),
    jewelCoreMaterial
  );
  jewelCore.name = 'jewel-highlight';
  jewelCore.position.set(-0.025, 0.03, 0.17);
  content.add(jewelCore);
  disposables.push(jewelCore.geometry, jewelCore.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.16,
    depthWrite: false,
  });

  const imagePlane = new Mesh(
    new PlaneGeometry(2.75, 0.15, 64, 64),
    imageMaterial
  );
  imagePlane.name = 'parallax-texture-plane';
  imagePlane.position.set(0, 0, 0.085);
  imagePlane.renderOrder = 2;
  content.add(imagePlane);
  disposables.push(imagePlane.geometry, imagePlane.material);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      resources.push(loadedTexture);
      imageMaterial.colorNode = texture(loadedTexture, uv());
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTexture) => {
      resources.push(depthTexture);
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(texture(depthTexture, uv()).r.mul(0.035))
      );
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const rimLight = new PointLight('#ff2a38', 0.42, 3.2, 2);
  rimLight.position.set(0.1, 0.28, 0.55);
  content.add(rimLight);

  const fillLight = new PointLight('#e8ecf2', 0.28, 2.8, 2);
  fillLight.position.set(-1.8, -0.25, 0.35);
  content.add(fillLight);

  const entrance = gsap.timeline();
  entrance.from(content.position, {
    y: 0.16,
    duration: 0.7,
    ease: 'power3.out',
  });
  entrance.fromTo(
    content.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );
  timelines.push(entrance);

  let hoverTween = null;
  let focusTween = null;

  root.userData.handlers = {
    hover(event) {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(content.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power3.out',
      });
      timelines.push(hoverTween);
    },

    blur(event) {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(content.position, {
        y: 0,
        duration: 0.42,
        ease: 'power3.out',
      });
      timelines.push(hoverTween);
    },

    focus(event) {
      if (focusTween) focusTween.kill();
      focusTween = gsap.to(edgeMaterial, {
        opacity: 0.92,
        duration: 0.2,
        ease: 'power2.out',
      });
      timelines.push(focusTween);
    },

    blurFocus(event) {
      if (focusTween) focusTween.kill();
      focusTween = gsap.to(edgeMaterial, {
        opacity: 0,
        duration: 0.25,
        ease: 'power2.out',
      });
      timelines.push(focusTween);
    },

    click(event) {
      const press = gsap.timeline();
      press.to(content.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      });
      press.to(content.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.32,
        ease: 'back.out(2.2)',
      });
      timelines.push(press);
      ctx.emit('hub-features.select', {
        node: 'hub-features-ornamental-divider',
      });
    },
  };

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    for (const item of disposables) {
      if (item && typeof item.dispose === 'function') item.dispose();
    }

    root.traverse((object) => {
      if (object.geometry && !disposables.includes(object.geometry)) {
        object.geometry.dispose();
      }
      if (object.material && !disposables.includes(object.material)) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material.dispose());
        } else {
          object.material.dispose();
        }
      }
    });
  };

  return root;
}
